function stats(scores){if(!scores.length)return null;var sum=0,mx=-Infinity,mn=Infinity;for(var i=0;i<scores.length;i++){var s=scores[i];sum+=s;if(s>mx)mx=s;if(s<mn)mn=s;}return {count:scores.length,sum:sum,average:sum/scores.length,max:mx,min:mn};}
function weighted(items){var tw=0,acc=0;for(var i=0;i<items.length;i++){tw+=items[i].weight;acc+=items[i].score*items[i].weight;}return tw?+(acc/tw).toFixed(4):null;}
function passRate(scores,line){var c=0;for(var i=0;i<scores.length;i++){if(scores[i]>=line)c++;}return {passed:c,total:scores.length,rate:c/scores.length};}
var EXPORTS={stats:stats,weighted:weighted,passRate:passRate};


